insert into k2q values
('r26_gp1','ae67be30-ec34-4ca8-a6cd-30e09917ffb4','41943719-23ce-4b07-9aaa-7e73981b0930','fill_blank','Un bilan qui cherche à isoler une seule articulation est qualifié d’____.','Le caractère analytique vise une articulation sans faire intervenir d’autres articulations.',2,'analytique','["analytique"]','eeeea5c9-b206-4661-8811-e7055683b215',1,'Le bilan doit être analytique : sur une seule articulation.'),
('r26_gp2','ae67be30-ec34-4ca8-a6cd-30e09917ffb4','41943719-23ce-4b07-9aaa-7e73981b0930','short_answer','Quels sont les trois plans anatomiques à connaître pour préparer un bilan articulaire ?','Le cours rappelle les plans frontal, sagittal et transversal.',2,'frontal, sagittal et transversal','["frontal sagittal transversal","plan frontal plan sagittal plan transversal","frontal, sagittal, transversal"]','eeeea5c9-b206-4661-8811-e7055683b215',1,'Rappel des plans : frontal, sagittal, transversal.'),
('r26_gh1','ae67be30-ec34-4ca8-a6cd-30e09917ffb4','58a31d41-8b23-4b38-b4b6-5eb9e9448145','fill_blank','La valeur de référence indiquée pour l’extension de hanche est de ____ degrés.','Le support retient 15° comme valeur de référence pour l’extension de hanche.',2,'15','["15","15 degrés","15°"]','eeeea5c9-b206-4661-8811-e7055683b215',3,'Norme extension = 15°.'),
('r26_gh2','ae67be30-ec34-4ca8-a6cd-30e09917ffb4','58a31d41-8b23-4b38-b4b6-5eb9e9448145','short_answer','Lors d’une mesure d’abduction de hanche, le goniomètre affiche 135°. Quelle amplitude faut-il retenir avec la lecture indirecte du cours ?','La valeur neutre est 90°, donc 135 - 90 = 45°.',3,'45 degrés','["45","45 degrés","45°"]','eeeea5c9-b206-4661-8811-e7055683b215',4,'Lecture indirecte : 135° - 90° = 45° d’abduction.'),
('r26_gg1','ae67be30-ec34-4ca8-a6cd-30e09917ffb4','7b29fe39-8a21-453f-8ed2-a238a2f0b570','fill_blank','La valeur de référence indiquée pour l’extension du genou se situe entre ____ et 10°.','Le support donne une extension comprise entre 0 et 10°.',2,'0','["0","0 degré","0°"]','eeeea5c9-b206-4661-8811-e7055683b215',5,'L’extension du genou : norme entre 0 et 10°.'),
('r26_gg2','ae67be30-ec34-4ca8-a6cd-30e09917ffb4','7b29fe39-8a21-453f-8ed2-a238a2f0b570','short_answer','Le cours donne-t-il une norme chiffrée particulière pour les rotations du genou ?','Le support précise qu’il n’y a pas de norme particulière pour les rotations du genou.',3,'non','["non","non aucune norme particulière","pas de norme","aucune norme"]','eeeea5c9-b206-4661-8811-e7055683b215',5,'Pas de normes attendues pour les rotations de genou.'),
('r26_ga1','ae67be30-ec34-4ca8-a6cd-30e09917ffb4','11faa2eb-c746-4d81-a394-679aa874d691','fill_blank','La flexion plantaire de cheville est donnée pour une amplitude de référence de ____ à 60°.','Le cours indique une norme de 45 à 60°.',2,'45','["45","45 degrés","45°"]','eeeea5c9-b206-4661-8811-e7055683b215',6,'La flexion plantaire : norme = 45-60°.'),
('r26_ga2','ae67be30-ec34-4ca8-a6cd-30e09917ffb4','11faa2eb-c746-4d81-a394-679aa874d691','short_answer','Si la lecture indirecte du goniomètre est de 72° en flexion dorsale de cheville, quelle amplitude retient-on avec la formule du cours ?','La formule est FD = 90 - mesure, soit 18°.',3,'18 degrés','["18","18 degrés","18°"]','eeeea5c9-b206-4661-8811-e7055683b215',7,'Lecture indirecte : FD = 90 - mesure.'),
('r26_er1','a0648d0d-92db-44e4-a700-06f273f78be2','df11df64-03fe-45ce-814b-8b8bd7f5c8f8','short_answer','Le secret professionnel de l’étudiant couvre-t-il seulement ce que le patient lui confie verbalement ?','Le secret couvre aussi ce qui a été vu, entendu ou compris.',3,'non, il couvre aussi ce qui est vu, entendu ou compris','["non","non il couvre aussi ce qui est vu entendu ou compris","vu entendu ou compris"]',(select id from public.course_documents where title='Ordre MK — Secret professionnel R.4321-55' limit 1),1,'Le secret professionnel s’impose aussi à l’étudiant et couvre ce qui a été confié, vu, entendu ou compris.'),
('r26_er2','a0648d0d-92db-44e4-a700-06f273f78be2','df11df64-03fe-45ce-814b-8b8bd7f5c8f8','short_answer','Quel principe interdit de traiter différemment un patient en raison d’un motif discriminatoire ?','Le code de déontologie impose une prise en charge sans discrimination.',3,'non-discrimination','["non discrimination","non-discrimination","absence de discrimination"]',(select id from public.course_documents where title='Ordre MK — Non-discrimination R.4321-58' limit 1),1,'Le masseur-kinésithérapeute examine, conseille ou soigne tous ses patients sans discrimination.'),
('r26_ec1','a0648d0d-92db-44e4-a700-06f273f78be2','18822448-c3e1-4375-8a86-0136a9d55cc7','short_answer','Quelles trois qualités le code de déontologie exige-t-il pour l’information donnée au patient ?','L’information doit être loyale, claire et appropriée.',3,'loyale, claire et appropriée','["loyale claire appropriée","loyale, claire et appropriée"]',(select id from public.course_documents where title='Ordre MK — Information du patient R.4321-83' limit 1),1,'Le professionnel doit une information loyale, claire et appropriée.'),
('r26_ec2','a0648d0d-92db-44e4-a700-06f273f78be2','18822448-c3e1-4375-8a86-0136a9d55cc7','short_answer','Un patient peut-il retirer son consentement après avoir accepté le début d’une prise en charge ?','Le consentement n’est pas définitif et peut être retiré à tout moment.',3,'oui, à tout moment','["oui","oui à tout moment","à tout moment"]',(select id from public.course_documents where title='Ordre MK — Consentement R.4321-84' limit 1),1,'Le consentement n’est pas définitivement acquis : la personne peut le retirer à tout moment.'),
('r26_es1','a0648d0d-92db-44e4-a700-06f273f78be2','a697dd68-02b0-470f-a28c-8c0b123f411e','short_answer','Cite un signal non verbal pouvant alerter le soignant sur un inconfort du patient.','Le cours cite notamment un patient qui se tend, se ferme ou montre des expressions de gêne.',3,'patient qui se tend ou se ferme','["patient qui se tend","patient qui se ferme","expression de gêne","expression d inconfort","gêne","inconfort"]','7bf8fc16-b190-4f94-b6c2-0bacf5b25a89',1,'Signaux d’alarme : patient qui se tend, se ferme, expressions de gêne ou d’inconfort.'),
('r26_es2','a0648d0d-92db-44e4-a700-06f273f78be2','a697dd68-02b0-470f-a28c-8c0b123f411e','short_answer','Pourquoi vaut-il mieux annoncer précisément le geste plutôt que dire seulement « je vais vous toucher » ?','Une annonce précise explique où et pourquoi le contact va avoir lieu et soutient un consentement éclairé et continu.',3,'pour expliquer précisément le geste et permettre un consentement éclairé','["pour expliquer précisément le geste","pour préciser où et pourquoi on touche","pour permettre le consentement","pour informer le patient"]','7bf8fc16-b190-4f94-b6c2-0bacf5b25a89',1,'Le cours oppose une annonce vague à une annonce précisant la zone et l’objectif du contact.'),
('r26_et1','f5dc6d1f-01e5-47f2-9160-64140734a8a3','135eb71d-9814-4823-a88d-cd3707a647dd','short_answer','Dans quelle position générale le cours recommande-t-il de réaliser un étirement passif pour favoriser la détente ?','Le support privilégie une position de repos, au minimum assise, plutôt que debout.',2,'position de repos','["position de repos","repos","assis ou allongé","position relâchée"]','8f2e4a6b-51f6-4aee-8d2a-9c819f53134b',1,'On réalise les étirements dans une position de repos qui favorise la détente.'),
('r26_et2','f5dc6d1f-01e5-47f2-9160-64140734a8a3','135eb71d-9814-4823-a88d-cd3707a647dd','fill_blank','Lors d’un étirement passif, la mise en tension est produite par une force ____ au sujet.','Le support définit l’étirement passif par une force extérieure au sujet.',2,'extérieure','["extérieure","exterieure","externe"]','8f2e4a6b-51f6-4aee-8d2a-9c819f53134b',1,'Étirements passifs : mise en tension due à une force extérieure au sujet.'),
('r26_ets1','f5dc6d1f-01e5-47f2-9160-64140734a8a3','4f8aa69c-329c-4e47-9b37-d89975baccf8','short_answer','Quels éléments individuels doivent guider l’adaptation d’un étirement ?','Le cours cite notamment l’âge, la condition physique et les antécédents de blessures.',3,'âge, condition physique et antécédents de blessures','["âge condition physique antécédents","age condition physique antecedents","âge, condition physique, antécédents"]','8f2e4a6b-51f6-4aee-8d2a-9c819f53134b',1,'Adapter selon l’âge, la condition physique et les antécédents de blessures.'),
('r26_ets2','f5dc6d1f-01e5-47f2-9160-64140734a8a3','4f8aa69c-329c-4e47-9b37-d89975baccf8','short_answer','Comment doit être relâchée la position après le temps de maintien d’un étirement ?','Le retour doit être progressif, comme la mise en tension.',2,'progressivement','["progressivement","de façon progressive","lentement"]','8f2e4a6b-51f6-4aee-8d2a-9c819f53134b',1,'La position est relâchée progressivement après 15 à 30 secondes.'),
('r26_ka1','33756c41-747b-4dd6-9ca5-209b0bd4afe0','1dc98a0c-f778-4423-b5f2-500a125712c8','short_answer','Cite deux objectifs thérapeutiques locaux possibles de la kinésithérapie active.','Le cours cite notamment la force, l’endurance et l’entretien des amplitudes articulaires.',2,'force et endurance','["force et endurance","augmentation de la force et endurance","force endurance","entretien des amplitudes et force"]','7bd7d4ac-0370-4e97-a25c-0d98bb993092',1,'Objectifs locaux : augmentation de la force, endurance, entretien des amplitudes articulaires.'),
('r26_ka2','33756c41-747b-4dd6-9ca5-209b0bd4afe0','1dc98a0c-f778-4423-b5f2-500a125712c8','short_answer','Quelle capacité proprioceptive faut-il vérifier avant de proposer un exercice actif ?','Le patient doit pouvoir contrôler l’exercice.',2,'capacité à contrôler l’exercice','["contrôler l exercice","capacité à contrôler","controle de l exercice","contrôle de l exercice"]','7bd7d4ac-0370-4e97-a25c-0d98bb993092',1,'Il faut vérifier que la personne a la capacité à contrôler l’exercice, aspect proprioceptif.'),
('r26_km1','33756c41-747b-4dd6-9ca5-209b0bd4afe0','5daf0156-c43a-403c-8341-637ea4cb7970','short_answer','Quel récepteur est associé au réflexe myotatique inverse dans le cours ?','Le réflexe myotatique inverse est associé à l’organe tendineux de Golgi.',3,'organe tendineux de Golgi','["organe tendineux de golgi","OTG","golgi"]','7bd7d4ac-0370-4e97-a25c-0d98bb993092',1,'Le réflexe myotatique inverse part de l’organe tendineux de Golgi.'),
('r26_km2','33756c41-747b-4dd6-9ca5-209b0bd4afe0','5daf0156-c43a-403c-8341-637ea4cb7970','fill_blank','Le phénomène de rétroaction utilisé dans l’apprentissage moteur est appelé ____.','Le support nomme ce phénomène feedback.',2,'feedback','["feedback","rétroaction","retroaction"]','7bd7d4ac-0370-4e97-a25c-0d98bb993092',2,'Phénomène de rétroaction = feedback.'),
('r26_kc1','33756c41-747b-4dd6-9ca5-209b0bd4afe0','898b119d-9dc0-40ef-872f-52b96b1252ac','short_answer','Quel rôle joue le muscle lors d’une contraction excentrique selon la balance des forces ?','Le muscle freine ou contrôle le mouvement tandis qu’il s’allonge.',3,'freiner ou contrôler le mouvement','["freiner le mouvement","contrôler le mouvement","action freinatrice","freinatrice"]','7bd7d4ac-0370-4e97-a25c-0d98bb993092',3,'En excentrique, l’action est freinatrice ou de contrôle du mouvement.'),
('r26_kc2','33756c41-747b-4dd6-9ca5-209b0bd4afe0','898b119d-9dc0-40ef-872f-52b96b1252ac','short_answer','Dans quelle course musculaire les insertions sont-elles les plus éloignées ?','La course externe correspond au muscle le plus long, proche de l’étirement.',2,'course externe','["course externe","externe"]','7bd7d4ac-0370-4e97-a25c-0d98bb993092',3,'Course externe : insertions les plus éloignées, muscle le plus long vers l’étirement.'),
('r26_kch1','33756c41-747b-4dd6-9ca5-209b0bd4afe0','3ff11e8a-c861-4a0e-a02c-9897d8dcd526','short_answer','De quoi dépend la résistance maximale d’une chaîne cinétique selon le cours ?','Elle ne dépasse pas la résistance du maillon le plus faible.',3,'du maillon le plus faible','["maillon le plus faible","du maillon le plus faible","élément le plus faible"]','7bd7d4ac-0370-4e97-a25c-0d98bb993092',3,'La résistance de la chaîne cinétique ne dépassera jamais la résistance du maillon le plus faible.'),
('r26_kch2','33756c41-747b-4dd6-9ca5-209b0bd4afe0','3ff11e8a-c861-4a0e-a02c-9897d8dcd526','short_answer','Se lever d’une chaise est donné comme exemple de quelle chaîne cinétique ?','Le cours utilise cet exemple pour une chaîne cinétique fermée, extrémité distale fixe.',2,'chaîne cinétique fermée','["chaîne fermée","chaine fermee","chaîne cinétique fermée","CCF"]','7bd7d4ac-0370-4e97-a25c-0d98bb993092',3,'Chaîne cinétique fermée : extrémité distale fixe, exemple se lever d’une chaise.'),
('r26_kap1','33756c41-747b-4dd6-9ca5-209b0bd4afe0','86033f6c-6d3a-418e-a58f-29a0ae5aeae6','short_answer','Dans un travail actif aidé, de quel côté de la balance des forces se place l’aide manuelle du thérapeute ?','L’aide du thérapeute est placée du côté de la force musculaire.',3,'du côté de la force musculaire','["force musculaire","côté force musculaire","du côté du muscle"]','b0728a83-f2e3-4be0-a0eb-d595a24e4a4b',1,'En kinésithérapie active aidée, le thérapeute aide du côté de la force musculaire.'),
('r26_kap2','33756c41-747b-4dd6-9ca5-209b0bd4afe0','86033f6c-6d3a-418e-a58f-29a0ae5aeae6','short_answer','Lors d’un travail concentrique contre résistance, quelle force doit être la plus grande pour produire le mouvement ?','La force musculaire doit dépasser la somme des forces extérieures.',3,'la force musculaire','["force musculaire","la force musculaire","force du muscle"]','b0728a83-f2e3-4be0-a0eb-d595a24e4a4b',1,'En concentrique, le patient doit vaincre la résistance et réaliser le mouvement.'),
('r26_me1','5ec8f27e-a958-4a35-b7ee-a3c2ad6abce2','5c19f9e8-da31-4b1b-9be5-abbc416e0817','short_answer','Quelle manœuvre est proposée pour la mise en route avant un pétrissage du quadriceps dans le cas clinique du cours ?','Le cas propose un effleurage profond longitudinal avant le pétrissage.',3,'effleurage profond longitudinal','["effleurage profond","effleurage profond longitudinal","effleurage longitudinal"]','feb65206-1bd0-4863-881d-16d6a51e51fb',1,'Technique pertinente : effleurage profond longitudinal pour mise en route puis pétrissage longitudinal.'),
('r26_me2','5ec8f27e-a958-4a35-b7ee-a3c2ad6abce2','5c19f9e8-da31-4b1b-9be5-abbc416e0817','short_answer','Quel principe de contact doit rester constant pendant un effleurage ?','Le support insiste sur la continuité du contact.',2,'ne pas perdre le contact','["ne pas perdre le contact","garder le contact","continuité du contact","contact continu"]','9b8e2b1d-e3ca-4d4e-ac92-f34beb6ea838',1,'Effleurage : ne jamais perdre le contact.'),
('r26_mg1','5ec8f27e-a958-4a35-b7ee-a3c2ad6abce2','b80de9e8-87c0-4f46-a966-7cd21b0fbbfc','short_answer','Quelle contre-indication absolue des pressions glissées est liée au risque d’embolie ?','Le support cite la thrombophlébite ou suspicion de phlébite.',3,'thrombophlébite ou suspicion de phlébite','["thrombophlébite","thrombophlebite","phlébite","suspicion de phlébite"]','f3a34484-bda6-444d-bb51-26f4f1f44a69',1,'Contre-indication absolue : thrombophlébite ou suspicion de phlébite, risque d’embolie.'),
('r26_mg2','5ec8f27e-a958-4a35-b7ee-a3c2ad6abce2','b80de9e8-87c0-4f46-a966-7cd21b0fbbfc','short_answer','En présence de varices importantes, quelle adaptation est recommandée pour les pressions ?','Le support conseille d’éviter les pressions profondes et de préférer l’effleurage doux.',3,'éviter les pressions profondes et préférer un effleurage doux','["éviter les pressions profondes","effleurage doux","préférer effleurage doux"]','f3a34484-bda6-444d-bb51-26f4f1f44a69',1,'Varices importantes : éviter les pressions profondes, préférer l’effleurage doux.'),
('r26_md1','5ec8f27e-a958-4a35-b7ee-a3c2ad6abce2','5a0004f6-ba14-4fc1-b401-0f976cd87d91','short_answer','Le drainage lymphatique manuel doit-il chercher à écraser les tissus ?','Non : la pression est légère, progressive et adaptée, sans chercher à écraser les tissus.',3,'non','["non","non pression légère","non il ne faut pas écraser les tissus"]','f3a34484-bda6-444d-bb51-26f4f1f44a69',2,'La pression est légère, progressive et adaptée ; le geste ne doit pas chercher à écraser les tissus.'),
('r26_md2','5ec8f27e-a958-4a35-b7ee-a3c2ad6abce2','5a0004f6-ba14-4fc1-b401-0f976cd87d91','short_answer','Dans un massage transversal profond, est-ce la main qui glisse sur la peau ?','Non : le geste est court et répété, sans glissement de la main sur la peau.',3,'non','["non","sans glissement","la main ne glisse pas"]','f3a34484-bda6-444d-bb51-26f4f1f44a69',2,'MTP : geste court, répété, sans glissement sur la peau.'),
('r26_mp1','5ec8f27e-a958-4a35-b7ee-a3c2ad6abce2','57374850-3c3f-46c9-85de-d37e84bc269b','short_answer','À quel moment de la séance le pétrissage est-il principalement placé ?','Le support le situe après l’échauffement, au cœur du travail musculaire.',2,'après l’échauffement, au cœur du massage','["après l échauffement","apres echauffement","au cœur du massage","phase de travail musculaire"]','feb65206-1bd0-4863-881d-16d6a51e51fb',1,'Pétrissage : après la phase d’échauffement, dans la phase de travail musculaire, au cœur du massage.'),
('r26_mp2','5ec8f27e-a958-4a35-b7ee-a3c2ad6abce2','57374850-3c3f-46c9-85de-d37e84bc269b','short_answer','Cite une contre-indication au pétrissage mentionnée dans le cours.','Le support cite notamment inflammation aiguë, plaie, dermatose, thrombophlébite, fièvre, infection ou trouble de coagulation.',3,'inflammation aiguë','["inflammation aiguë","plaie","dermatose","thrombophlébite","fièvre","infection","trouble de coagulation"]','feb65206-1bd0-4863-881d-16d6a51e51fb',1,'Contre-indications : inflammations aiguës, plaies et dermatoses, thrombophlébite, fièvre et infection, troubles de la coagulation.'),
('r26_mo1','fffb5451-b18e-47ba-a3d8-2886e415b257','148741d4-9b51-4974-ac56-a4ff6859ed56','short_answer','Quels deux types de glissement de hanche sont décrits en plus de la décoaptation longitudinale ?','Le TP décrit des glissements antérieur et postérieur.',2,'glissements antérieur et postérieur','["antérieur et postérieur","glissement antérieur et postérieur","antérieur postérieur"]','f26d2658-d523-4c4e-b8a2-671424e85822',1,'Le TP décrit décoaptation longitudinale et glissements antérieur/postérieur.'),
('r26_mo2','fffb5451-b18e-47ba-a3d8-2886e415b257','148741d4-9b51-4974-ac56-a4ff6859ed56','short_answer','Que signifie « décoaptation » dans le contexte de la mobilisation articulaire spécifique ?','Il s’agit d’une séparation contrôlée des surfaces articulaires.',3,'séparation contrôlée des surfaces articulaires','["séparation des surfaces articulaires","séparation contrôlée des surfaces articulaires","écarter les surfaces articulaires"]','f26d2658-d523-4c4e-b8a2-671424e85822',1,'Décoaptation : séparation contrôlée des surfaces articulaires.');
