-- Enrichissement K2 Rééducation : 38 questions nouvelles et non redondantes, toutes sourcées.
-- Inclut quatre références officielles du Conseil national de l'Ordre des masseurs-kinésithérapeutes.

select v.title,'a5dc885f-434c-43e6-ab6f-777b50417ce8'::uuid,'3ced4727-bf07-4d20-9c76-13d44b54c6f6'::uuid,'a0648d0d-92db-44e4-a700-06f273f78be2'::uuid,v.file_name,v.url,'text/html','reference','processed','validated'
from (values
 ('Ordre MK — Secret professionnel R.4321-55','ordre-r4321-55.html','https://deontologie.ordremk.fr/devoirs-generaux-des-masseurs-kinesitherapeutes/r-4321-55-secret-professionnel/'),
 ('Ordre MK — Non-discrimination R.4321-58','ordre-r4321-58.html','https://deontologie.ordremk.fr/devoirs-generaux-des-masseurs-kinesitherapeutes/r-4321-58-non-discrimination/'),
 ('Ordre MK — Information du patient R.4321-83','ordre-r4321-83.html','https://deontologie.ordremk.fr/devoirs-envers-les-patients/r-4321-83-information-du-malade/'),
 ('Ordre MK — Consentement R.4321-84','ordre-r4321-84.html','https://deontologie.ordremk.fr/devoirs-envers-les-patients/r-4321-84-consentement-du-malade/')
) v(title,file_name,url)
where not exists(select 1 from public.course_documents cd where cd.title=v.title);

create temporary table k2q(batch_key text primary key,chapter_id uuid,lesson_id uuid,qtype text,question_text text,explanation text,difficulty int,answer text,accepted_answers jsonb,document_id uuid,page_number int,source_excerpt text) on commit drop;


select k.chapter_id,k.lesson_id,k.qtype,k.question_text,k.explanation,k.difficulty,
       jsonb_build_object('answer',k.answer,'accepted_answers',k.accepted_answers,'batch_tag','k2_reeducation_expand_20261004','content_key',k.batch_key,'learning_format',k.qtype,'source_page',k.page_number,'source_excerpt',k.source_excerpt),
       cd.title,false,'draft',cd.title
from k2q k join public.course_documents cd on cd.id=k.document_id
where not exists(select 1 from public.questions q where lower(btrim(q.question_text))=lower(btrim(k.question_text)));

select q.id,k.document_id,k.lesson_id,k.page_number,k.source_excerpt
from k2q k join public.questions q on q.metadata->>'content_key'=k.batch_key
where not exists(select 1 from public.question_sources qs where qs.question_id=q.id and qs.document_id=k.document_id and qs.page_number=k.page_number);

update public.questions q
set is_published=true,validation_status='published',validated_at=now(),updated_at=now()
where q.metadata->>'batch_tag'='k2_reeducation_expand_20261004' and q.is_published=false;
